import{_ as i,c as r,o as t,a2 as s}from"./chunks/framework.DcjMSgeM.js";const h=JSON.parse('{"title":"Exercices pratiques","description":"","frontmatter":{},"headers":[],"relativePath":"seances/9_securite/exercices.md","filePath":"seances/9_securite/exercices.md","lastUpdated":1792669431000}'),a={name:"seances/9_securite/exercices.md"};function n(c,e,o,l,u,d){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="exercices" tabindex="-1">Exercices pratiques <a class="header-anchor" href="#exercices" aria-label="Permalink to &quot;Exercices pratiques {#exercices}&quot;">​</a></h1><p>Mettez en pratique les notions du chapitre Sécurité. Chaque exercice cible une compétence concrète (auth, XSS, audit, HTTPS).</p><h2 id="exercice-1-securisation-d-une-api-de-connexion" tabindex="-1">Exercice 1 : Sécurisation d&#39;une API de connexion <a class="header-anchor" href="#exercice-1-securisation-d-une-api-de-connexion" aria-label="Permalink to &quot;Exercice 1 : Sécurisation d&#39;une API de connexion&quot;">​</a></h2><p><strong>Objectif</strong> : Implémenter une authentification sécurisée</p><p><strong>Tâches</strong> :</p><ol><li>Créer un endpoint de connexion avec validation</li><li>Implémenter le hachage des mots de passe</li><li>Générer et valider des JWT</li><li>Ajouter une limitation du taux de requêtes</li></ol><h2 id="exercice-2-protection-contre-xss" tabindex="-1">Exercice 2 : Protection contre XSS <a class="header-anchor" href="#exercice-2-protection-contre-xss" aria-label="Permalink to &quot;Exercice 2 : Protection contre XSS&quot;">​</a></h2><p><strong>Objectif</strong> : Sécuriser une application contre les attaques XSS</p><p><strong>Tâches</strong> :</p><ol><li>Identifier les vulnérabilités XSS dans le code fourni</li><li>Implémenter la sanitisation des données</li><li>Configurer CSP</li><li>Tester les protections</li></ol><h2 id="exercice-3-audit-de-securite" tabindex="-1">Exercice 3 : Audit de sécurité <a class="header-anchor" href="#exercice-3-audit-de-securite" aria-label="Permalink to &quot;Exercice 3 : Audit de sécurité&quot;">​</a></h2><p><strong>Objectif</strong> : Effectuer un audit complet d&#39;une application</p><p><strong>Tâches</strong> :</p><ol><li>Scanner les vulnérabilités avec npm audit</li><li>Analyser les headers de sécurité</li><li>Tester les mécanismes d&#39;authentification</li><li>Proposer des améliorations</li></ol><h2 id="exercice-4-implementation-https" tabindex="-1">Exercice 4 : Implémentation HTTPS <a class="header-anchor" href="#exercice-4-implementation-https" aria-label="Permalink to &quot;Exercice 4 : Implémentation HTTPS&quot;">​</a></h2><p><strong>Objectif</strong> : Configurer HTTPS et les headers de sécurité</p><p><strong>Tâches</strong> :</p><ol><li>Générer des certificats SSL</li><li>Configurer le serveur HTTPS</li><li>Implémenter HSTS</li><li>Rediriger HTTP vers HTTPS</li></ol><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La sécurité des applications web est un domaine en constante évolution qui nécessite une vigilance permanente. Les concepts abordés dans ce chapitre constituent les fondements essentiels pour développer des applications web sécurisées.</p><h3 id="points-cles-a-retenir" tabindex="-1">Points clés à retenir <a class="header-anchor" href="#points-cles-a-retenir" aria-label="Permalink to &quot;Points clés à retenir&quot;">​</a></h3><ul><li>La sécurité doit être intégrée dès la conception</li><li>Toujours valider et sanitiser les données d&#39;entrée</li><li>Utiliser HTTPS et des headers de sécurité appropriés</li><li>Implémenter une authentification et autorisation robustes</li><li>Maintenir les dépendances à jour</li><li>Effectuer des tests de sécurité réguliers</li></ul><h3 id="ressources-supplementaires" tabindex="-1">Ressources supplémentaires <a class="header-anchor" href="#ressources-supplementaires" aria-label="Permalink to &quot;Ressources supplémentaires&quot;">​</a></h3><ul><li><a href="https://owasp.org/Top10/2025/" target="_blank" rel="noreferrer">OWASP Top 10:2025</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Web/Security" target="_blank" rel="noreferrer">MDN Web Security</a></li><li><a href="https://nodejs.org/en/docs/guides/security/" target="_blank" rel="noreferrer">Node.js Security Best Practices</a></li><li><a href="https://expressjs.com/en/advanced/best-practice-security.html" target="_blank" rel="noreferrer">Express.js Security Best Practices</a></li></ul><hr><p>← <a href="./pratiques.html">Pratiques et outils</a> · <a href="./">Retour à la vue d&#39;ensemble</a></p>',26)])])}const m=i(a,[["render",n]]);export{h as __pageData,m as default};
